namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ──────────────────────────────────────────────
    // CalculateTotal — DataRow (compile-time constants)
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0, 20.00, DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Multiple items, 8% tax")]
    [DataRow(0.00, 5, 0.20, 0.00, DisplayName = "Zero price, any quantity")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity returns zero")]
    public void CalculateTotal_ValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ──────────────────────────────────────────────
    // CalculateTotal — DynamicData (complex/edge cases)
    // ──────────────────────────────────────────────

    public static IEnumerable<object[]> CalculateTotalEdgeCases
    {
        get
        {
            yield return new object[] { 0.01m, 1, 0m, 0.01m, "Minimum meaningful price" };
            yield return new object[] { 9999.99m, 100, 1m, 1_999_998.00m, "Large order with max tax" };
            yield return new object[] { 5.00m, 1, 0.0725m, 5.3625m, "Fractional tax rate" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(CalculateTotalEdgeCases))]
    public void CalculateTotal_EdgeCases_ReturnsExpected(
        decimal unitPrice, int quantity, decimal taxRate, decimal expected, string scenario)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expected, result, $"Failed for scenario: {scenario}");
    }

    // ──────────────────────────────────────────────
    // CalculateTotal — invalid inputs throw
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, DisplayName = "Negative unit price throws")]
    public void CalculateTotal_NegativePrice_Throws(double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity throws")]
    public void CalculateTotal_NegativeQuantity_Throws(double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DataRow(10.00, 1, -0.01, DisplayName = "Tax rate below 0 throws")]
    [DataRow(10.00, 1, 1.01, DisplayName = "Tax rate above 1 throws")]
    public void CalculateTotal_InvalidTaxRate_Throws(double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ──────────────────────────────────────────────
    // ApplyDiscount — DataRow
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(100.00, 0.0, 100.00, DisplayName = "0% discount — full price")]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% discount")]
    [DataRow(100.00, 50.0, 50.00, DisplayName = "50% discount")]
    [DataRow(100.00, 100.0, 0.00, DisplayName = "100% discount — free")]
    [DataRow(49.99, 25.0, 37.4925, DisplayName = "Non-round price and discount")]
    public void ApplyDiscount_ValidInputs_ReturnsExpected(
        double price, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    // ──────────────────────────────────────────────
    // ApplyDiscount — DynamicData (boundary & precision)
    // ──────────────────────────────────────────────

    public static IEnumerable<object[]> ApplyDiscountBoundaryData
    {
        get
        {
            yield return new object[] { 200.00m, 0.01m, 199.98m, "Smallest meaningful discount" };
            yield return new object[] { 200.00m, 99.99m, 0.02m, "Largest sub-100% discount" };
            yield return new object[] { 0m, 50m, 0m, "Zero price unaffected by discount" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountBoundaryData))]
    public void ApplyDiscount_BoundaryCases_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result, $"Failed for scenario: {scenario}");
    }

    // ──────────────────────────────────────────────
    // ApplyDiscount — invalid inputs throw
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(100.00, -1.0, DisplayName = "Negative discount throws")]
    [DataRow(100.00, 100.01, DisplayName = "Discount > 100 throws")]
    public void ApplyDiscount_InvalidDiscount_Throws(double price, double discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent));
    }
}

